#include <omp.h>
#include <algorithm>
#include <limits>
#include <stdexcept>
#include <vector>

double sumOfMinimumElements(std::vector<double> const& x, std::vector<double> const& y) {
    if (x.size() != y.size()) {
        throw std::invalid_argument("sumOfMinimumElements: x and y must have the same size");
    }

    if (x.empty()) {
        return 0.0;
    }

    if (x.size() > static_cast<std::size_t>(std::numeric_limits<long long>::max())) {
        throw std::overflow_error("sumOfMinimumElements: input size exceeds supported OpenMP loop range");
    }

    const long long n = static_cast<long long>(x.size());
    double sum = 0.0;

    #pragma omp parallel for reduction(+:sum) schedule(static)
    for (long long i = 0; i < n; ++i) {
        sum += std::min(x[static_cast<std::size_t>(i)], y[static_cast<std::size_t>(i)]);
    }

    return sum;
}
